def count_partitions(n: int, k: int, x: int) -> int:
    if n < 0 or k < 0 or x < 0:
        return 0
    if n < k * x:
        return 0
    if n == 0 or k == 0:
        return 1
    return count_partitions(n - x, k, x) + count_partitions(n, k - 1, x)
