def count_sequences(n, last, memo):
    if last in memo:
        return memo[last]
    if n > last or n <= 0:
        return 0
    if n == last:
        return 1
    count = 0
    for i in range(n, last):
        count += count_sequences(n, i, memo)
    memo[last] = count
    return count
